mapper.insert:
MERGE INTO BC_SPORTS_BCP_SPORT_POINTS target USING (
SELECT #{item.sporter} AS sporter, #{item.points} AS points, #{item.createBy} AS create_by, #{item.updateBy} AS update_by FROM dual
) source ON (target.sporter = source.sporter AND target.deleted = 0) WHEN MATCHED THEN UPDATE SET target.points = source.points, target.update_time = SYSTIMESTAMP, target.update_by = source.update_by WHEN NOT MATCHED THEN INSERT (sporter, points, create_time, update_time, create_by, update_by, deleted) VALUES (source.sporter, source.points, SYSTIMESTAMP, SYSTIMESTAMP, source.create_by, source.update_by, 0)
